$img = [System.Drawing.Bitmap]::FromFile("<home>\source\repos\priv\monster-dev-testruns\2026-08-01-phase1.dist\monster-walk.png")
$rect = New-Object System.Drawing.Rectangle 0,0,$img.Width,$img.Height
$data = $img.LockBits($rect, [System.Drawing.Imaging.ImageLockMode]::ReadOnly, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
$stride = $data.Stride
$bytes = New-Object byte[] ($stride * $img.Height)
[System.Runtime.InteropServices.Marshal]::Copy($data.Scan0, $bytes, 0, $bytes.Length)
$img.UnlockBits($data)
# bottom 25 rows = feet contact zone
$globalMin = 9999; $globalMax = -1; $bottomRow = -1
for ($f = 0; $f -lt 23; $f++) {
  $min = 9999; $max = -1
  for ($y = $img.Height - 25; $y -lt $img.Height; $y++) {
    for ($x = 0; $x -lt 276; $x++) {
      $gx = $f * 276 + $x
      $a = $bytes[$y * $stride + $gx * 4 + 3]
      if ($a -gt 128) { if ($x -lt $min) { $min = $x }; if ($x -gt $max) { $max = $x }; if ($y -gt $bottomRow) { $bottomRow = $y } }
    }
  }
  if ($max -ge 0) { "frame {0,2}: feet x {1,3}..{2,3}" -f $f, $min, $max }
  if ($min -lt $globalMin) { $globalMin = $min }
  if ($max -gt $globalMax) { $globalMax = $max }
}
"GLOBAL feet span: $globalMin .. $globalMax  (of 276)  lowest opaque row: $bottomRow of $($img.Height)"
$img.Dispose()

