// Throwaway CDP driver: load the page, press Alt+A, screenshot the walk.
import { writeFileSync } from 'node:fs';

const BASE = 'http://127.0.0.1:8765/index.html';
const OUT = process.argv[2];

const listTargets = async () => (await fetch('http://127.0.0.1:9222/json/list')).json();

let pages = [];
for (let i = 0; i < 40; i++) {
  try {
    pages = (await listTargets()).filter((t) => t.type === 'page');
    if (pages.length) break;
  } catch {}
  await new Promise((r) => setTimeout(r, 250));
}
if (!pages.length) throw new Error('no page target');

const ws = new WebSocket(pages[0].webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));

let id = 0;
const pending = new Map();
ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg.result ?? msg.error);
    pending.delete(msg.id);
  }
};
const send = (method, params = {}) =>
  new Promise((resolve) => {
    const mid = ++id;
    pending.set(mid, resolve);
    ws.send(JSON.stringify({ id: mid, method, params }));
  });

const wait = (ms) => new Promise((r) => setTimeout(r, ms));

await send('Page.enable');
await send('Runtime.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url: BASE });
await wait(2500);

const shot = async (name) => {
  const res = await send('Page.captureScreenshot', { format: 'png' });
  writeFileSync(`${OUT}\\${name}.png`, Buffer.from(res.data, 'base64'));
};

